def run_supervisor(plan, workers, max_delegations=3):
    if len(plan) > max_delegations:
        raise ValueError('delegation budget exceeded')
    results = []
    for item in plan:
        name = item['worker']
        if name not in workers:
            raise ValueError(f'unknown worker: {name}')
        results.append({'task_id': item['task_id'], 'result': workers[name](item['input'])})
    return results
